BEGIN;
ALTER TABLE public.media_cleanup_jobs ADD COLUMN IF NOT EXISTS idempotency_key text,ADD COLUMN IF NOT EXISTS lease_until timestamptz,ADD COLUMN IF NOT EXISTS worker_id text,ADD COLUMN IF NOT EXISTS lock_token uuid,ADD COLUMN IF NOT EXISTS max_attempts int NOT NULL DEFAULT 12,ADD COLUMN IF NOT EXISTS completed_at timestamptz;
UPDATE public.media_cleanup_jobs SET idempotency_key='legacy:'||id WHERE idempotency_key IS NULL;
ALTER TABLE public.media_cleanup_jobs ALTER idempotency_key SET NOT NULL,DROP CONSTRAINT IF EXISTS media_cleanup_jobs_status_check;
ALTER TABLE public.media_cleanup_jobs ADD CHECK(status IN('PENDING','PROCESSING','RETRY','DONE','FAILED')),ADD CHECK(attempt_count>=0 AND max_attempts>0);
CREATE UNIQUE INDEX media_cleanup_jobs_idem_uq ON public.media_cleanup_jobs(idempotency_key);
CREATE INDEX media_cleanup_jobs_ready ON public.media_cleanup_jobs(next_attempt_at) WHERE status IN('PENDING','RETRY');
CREATE TABLE public.listing_purge_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),listing_id uuid,expected_status text NOT NULL CHECK(expected_status IN('REMOVED','SOLD','EXPIRED')),reason text NOT NULL,retention_anchor timestamptz NOT NULL,purge_after timestamptz NOT NULL,media_keys jsonb NOT NULL CHECK(jsonb_typeof(media_keys)='array'),status text NOT NULL DEFAULT 'PENDING' CHECK(status IN('PENDING','PROCESSING','RETRY','DONE','FAILED','CANCELLED')),attempts int NOT NULL DEFAULT 0 CHECK(attempts>=0),max_attempts int NOT NULL DEFAULT 12 CHECK(max_attempts>0),next_attempt_at timestamptz NOT NULL DEFAULT now(),lease_until timestamptz,worker_id text,lock_token uuid,last_error text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,idempotency_key text NOT NULL UNIQUE);
CREATE INDEX listing_purge_ready ON public.listing_purge_jobs(next_attempt_at) WHERE status IN('PENDING','RETRY');
ALTER TABLE public.offer_threads ADD COLUMN original_listing_id uuid,ADD COLUMN listing_snapshot jsonb;
UPDATE public.offer_threads t SET original_listing_id=t.listing_id,listing_snapshot=to_jsonb(l) FROM public.listings l WHERE l.id=t.listing_id;
ALTER TABLE public.offer_threads ALTER original_listing_id SET NOT NULL,ALTER listing_id DROP NOT NULL,DROP CONSTRAINT offer_threads_listing_id_fkey,ADD FOREIGN KEY(listing_id) REFERENCES public.listings ON DELETE SET NULL;
ALTER TABLE public.reports ADD COLUMN historical_listing_id uuid,ADD COLUMN listing_snapshot jsonb;
UPDATE public.reports r SET historical_listing_id=r.listing_id,listing_snapshot=to_jsonb(l) FROM public.listings l WHERE l.id=r.listing_id;
ALTER TABLE public.reports ALTER historical_listing_id SET NOT NULL,ALTER listing_id DROP NOT NULL,DROP CONSTRAINT reports_listing_id_fkey,ADD FOREIGN KEY(listing_id) REFERENCES public.listings ON DELETE SET NULL;
ALTER TABLE public.payments ADD COLUMN historical_target_listing_id uuid,ADD COLUMN target_listing_snapshot jsonb;
UPDATE public.payments p SET historical_target_listing_id=p.target_listing_id,target_listing_snapshot=to_jsonb(l) FROM public.listings l WHERE l.id=p.target_listing_id;
ALTER TABLE public.listing_purge_jobs ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.listing_purge_jobs,public.media_cleanup_jobs FROM PUBLIC,anon,authenticated; GRANT ALL ON public.listing_purge_jobs,public.media_cleanup_jobs TO service_role;
CREATE FUNCTION public.canonical_sanboard_media_key(v text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public AS $$SELECT CASE WHEN v IS NULL OR btrim(v)='' OR v LIKE 'data:%' THEN NULL WHEN v ~ '^/?(avatars/|listings/|dealers/logos/|dealers/banners/)' THEN regexp_replace(v,'^/+','') WHEN v ~ '^https?://([^/]*r2\.dev|sanboard-media\.esin18457\.workers\.dev|cdn\.sanboard\.xyz)/(avatars/|listings/|dealers/logos/|dealers/banners/)' THEN regexp_replace(v,'^https?://[^/]+/','') ELSE NULL END$$;
CREATE FUNCTION public.is_media_key_referenced(k text,x uuid DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$SELECT EXISTS(SELECT 1 FROM listing_images WHERE canonical_sanboard_media_key(storage_path)=k AND (x IS NULL OR listing_id<>x)) OR EXISTS(SELECT 1 FROM character_profiles WHERE canonical_sanboard_media_key(avatar_path)=k OR canonical_sanboard_media_key(avatar_url)=k) OR EXISTS(SELECT 1 FROM corporate_profiles WHERE canonical_sanboard_media_key(logo_path)=k OR canonical_sanboard_media_key(logo_url)=k OR canonical_sanboard_media_key(banner_path)=k OR canonical_sanboard_media_key(banner_url)=k)$$;
CREATE FUNCTION public.enqueue_media_cleanup_job(k text,t text,r text,i text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE x uuid;BEGIN IF nullif(btrim(k),'') IS NULL OR nullif(btrim(i),'') IS NULL THEN RAISE EXCEPTION 'key required';END IF;INSERT INTO media_cleanup_jobs(object_key,media_type,reason,idempotency_key) VALUES(k,t,r,i) ON CONFLICT(idempotency_key) DO UPDATE SET object_key=excluded.object_key RETURNING id INTO x;RETURN x;END$$;
CREATE FUNCTION public.enqueue_listing_purge_job(lid uuid,r text DEFAULT 'RETENTION') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE l listings%rowtype;a timestamptz;p timestamptz;k jsonb;j uuid;BEGIN SELECT * INTO l FROM listings WHERE id=lid FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'listing not found';END IF;IF l.status='REMOVED' THEN a:=coalesce(l.closed_at,l.updated_at);p:=a;ELSIF l.status='SOLD' THEN a:=l.closed_at;p:=a+interval '24 hours';ELSIF l.status='EXPIRED' THEN a:=l.expires_at;p:=a+interval '7 days';ELSE RAISE EXCEPTION 'not purgeable';END IF;IF a IS NULL THEN RAISE EXCEPTION 'anchor null';END IF;SELECT coalesce(jsonb_agg(storage_path ORDER BY storage_path),'[]') INTO k FROM(SELECT DISTINCT storage_path FROM listing_images WHERE listing_id=lid)s;INSERT INTO listing_purge_jobs(listing_id,expected_status,reason,retention_anchor,purge_after,media_keys,next_attempt_at,idempotency_key)VALUES(lid,l.status,r,a,p,k,p,'purge:'||lid||':'||l.status||':'||a)ON CONFLICT(idempotency_key)DO UPDATE SET updated_at=now() RETURNING id INTO j;PERFORM enqueue_media_cleanup_job(x,'LISTING_IMAGE','LISTING_PURGE','purge:'||j||':'||x)FROM jsonb_array_elements_text(k)x;RETURN j;END$$;
CREATE FUNCTION public.discover_listing_purge_jobs(n int DEFAULT 500) RETURNS int LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE r record;c int:=0;BEGIN FOR r IN SELECT id FROM listings WHERE status='REMOVED' OR(status='SOLD' AND closed_at<=now()-interval '24 hours')OR(status='EXPIRED' AND expires_at<=now()-interval '7 days')LIMIT n LOOP PERFORM enqueue_listing_purge_job(r.id,'DISCOVERY');c:=c+1;END LOOP;RETURN c;END$$;
CREATE FUNCTION public.claim_listing_purge_jobs(w text,n int DEFAULT 25,s int DEFAULT 300) RETURNS SETOF listing_purge_jobs LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$BEGIN RETURN QUERY WITH q AS(SELECT id FROM listing_purge_jobs WHERE(status IN('PENDING','RETRY')AND next_attempt_at<=now()AND attempts<max_attempts)OR(status='PROCESSING'AND lease_until<now())ORDER BY next_attempt_at FOR UPDATE SKIP LOCKED LIMIT n)UPDATE listing_purge_jobs j SET status='PROCESSING',attempts=j.attempts+1,lease_until=now()+make_interval(secs=>s),worker_id=w,lock_token=gen_random_uuid(),updated_at=now()FROM q WHERE j.id=q.id RETURNING j.*;END$$;
CREATE FUNCTION public.retry_listing_purge_job(i uuid,t uuid,e text)RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE b boolean;BEGIN UPDATE listing_purge_jobs SET status=CASE WHEN attempts>=max_attempts THEN'FAILED'ELSE'RETRY'END,next_attempt_at=now()+least(interval'24 hours',interval'30 seconds'*power(2,attempts-1)),last_error=left(e,4000),lease_until=NULL,worker_id=NULL,lock_token=NULL,completed_at=CASE WHEN attempts>=max_attempts THEN now()END WHERE id=i AND status='PROCESSING'AND lock_token=t RETURNING true INTO b;RETURN coalesce(b,false);END$$;
CREATE FUNCTION public.claim_media_cleanup_jobs(w text,n int DEFAULT 50,s int DEFAULT 300)RETURNS SETOF media_cleanup_jobs LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$BEGIN RETURN QUERY WITH q AS(SELECT id FROM media_cleanup_jobs WHERE(status IN('PENDING','RETRY')AND next_attempt_at<=now()AND attempt_count<max_attempts)OR(status='PROCESSING'AND lease_until<now())ORDER BY next_attempt_at FOR UPDATE SKIP LOCKED LIMIT n)UPDATE media_cleanup_jobs j SET status='PROCESSING',attempt_count=j.attempt_count+1,lease_until=now()+make_interval(secs=>s),worker_id=w,lock_token=gen_random_uuid(),updated_at=now()FROM q WHERE j.id=q.id RETURNING j.*;END$$;
CREATE FUNCTION public.complete_media_cleanup_job(i uuid,t uuid)RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE b boolean;BEGIN UPDATE media_cleanup_jobs SET status='DONE',completed_at=now(),lease_until=NULL,worker_id=NULL,lock_token=NULL,last_error=NULL WHERE id=i AND status='PROCESSING'AND lock_token=t AND lease_until>=now()AND NOT is_media_key_referenced(object_key)RETURNING true INTO b;RETURN coalesce(b,false);END$$;
CREATE FUNCTION public.retry_media_cleanup_job(i uuid,t uuid,e text)RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE b boolean;BEGIN UPDATE media_cleanup_jobs SET status=CASE WHEN attempt_count>=max_attempts THEN'FAILED'ELSE'RETRY'END,next_attempt_at=now()+least(interval'24 hours',interval'30 seconds'*power(2,attempt_count-1)),last_error=left(e,4000),lease_until=NULL,worker_id=NULL,lock_token=NULL,completed_at=CASE WHEN attempt_count>=max_attempts THEN now()END WHERE id=i AND status='PROCESSING'AND lock_token=t RETURNING true INTO b;RETURN coalesce(b,false);END$$;
CREATE FUNCTION public.requeue_media_cleanup_job(i uuid)RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE b boolean;BEGIN UPDATE media_cleanup_jobs SET status='PENDING',attempt_count=0,next_attempt_at=now(),completed_at=NULL,last_error=NULL WHERE id=i AND status='FAILED'RETURNING true INTO b;RETURN coalesce(b,false);END$$;
CREATE FUNCTION public.replace_listing_images_atomic(p_listing_id uuid,p_images jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE l listings%rowtype;old text[];k text;c int:=0;image_count int;BEGIN IF jsonb_typeof(p_images)<>'array'THEN RAISE EXCEPTION 'invalid images';END IF;SELECT * INTO l FROM listings WHERE id=p_listing_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'listing not found';END IF;image_count:=jsonb_array_length(p_images);IF image_count<1 THEN RAISE EXCEPTION 'invalid images';END IF;IF l.category='vehicle'AND image_count>3 THEN RAISE EXCEPTION 'invalid images';END IF;IF l.category='property'AND image_count>5 THEN RAISE EXCEPTION 'invalid images';END IF;IF l.category NOT IN('vehicle','property')THEN RAISE EXCEPTION 'invalid listing category';END IF;IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_images)x WHERE nullif(btrim(x->>'storage_path'),'')IS NULL OR coalesce((x->>'size_bytes')::int,0)NOT BETWEEN 1 AND 2097152)OR(SELECT count(*)FROM jsonb_array_elements(p_images)x WHERE coalesce((x->>'is_cover')::boolean,false))<>1 THEN RAISE EXCEPTION 'invalid images';END IF;SELECT array_agg(storage_path)INTO old FROM listing_images WHERE listing_id=p_listing_id;DELETE FROM listing_images WHERE listing_id=p_listing_id;INSERT INTO listing_images(listing_id,storage_path,sort_order,is_cover,size_bytes)SELECT p_listing_id,x->>'storage_path',coalesce((x->>'sort_order')::smallint,0),coalesce((x->>'is_cover')::boolean,false),(x->>'size_bytes')::int FROM jsonb_array_elements(p_images)x;FOREACH k IN ARRAY coalesce(old,ARRAY[]::text[])LOOP IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_images)x WHERE x->>'storage_path'=k)THEN PERFORM enqueue_media_cleanup_job(k,'LISTING_IMAGE','LISTING_IMAGE_REPLACED','replace:'||p_listing_id||':'||k);c:=c+1;END IF;END LOOP;RETURN jsonb_build_object('success',true,'cleanup_jobs',c);END$$;
CREATE FUNCTION public.complete_listing_purge_media_key(i uuid,t uuid,k text)RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE b boolean;BEGIN UPDATE media_cleanup_jobs m SET status='DONE',completed_at=now(),last_error=NULL,lease_until=NULL,worker_id=NULL,lock_token=NULL,updated_at=now() FROM listing_purge_jobs j WHERE j.id=i AND j.status='PROCESSING' AND j.lock_token=t AND j.lease_until>=now() AND m.idempotency_key='purge:'||j.id||':'||k AND EXISTS(SELECT 1 FROM jsonb_array_elements_text(j.media_keys)x WHERE x=k) RETURNING true INTO b;RETURN coalesce(b,false);END$$;
CREATE FUNCTION public.finalize_listing_purge(i uuid,t uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$DECLARE j listing_purge_jobs%rowtype;l listings%rowtype;snap jsonb;a timestamptz;BEGIN SELECT * INTO j FROM listing_purge_jobs WHERE id=i FOR UPDATE;IF NOT FOUND OR j.status<>'PROCESSING'OR j.lock_token IS DISTINCT FROM t OR j.lease_until<now()THEN RETURN jsonb_build_object('success',false,'result','INVALID_LEASE');END IF;SELECT * INTO l FROM listings WHERE id=j.listing_id FOR UPDATE;IF NOT FOUND THEN UPDATE listing_purge_jobs SET status='CANCELLED',completed_at=now(),last_error='listing missing',lease_until=NULL,worker_id=NULL,lock_token=NULL WHERE id=i;RETURN jsonb_build_object('success',false,'result','CANCELLED_MISSING');END IF;a:=CASE l.status WHEN'REMOVED'THEN coalesce(l.closed_at,l.updated_at)WHEN'SOLD'THEN l.closed_at WHEN'EXPIRED'THEN l.expires_at END;IF l.status<>j.expected_status OR a IS DISTINCT FROM j.retention_anchor OR now()<j.purge_after THEN UPDATE listing_purge_jobs SET status='CANCELLED',completed_at=now(),last_error='lifecycle changed',lease_until=NULL,worker_id=NULL,lock_token=NULL WHERE id=i;RETURN jsonb_build_object('success',false,'result','CANCELLED_STALE');END IF;IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(j.media_keys)k WHERE NOT EXISTS(SELECT 1 FROM media_cleanup_jobs m WHERE m.idempotency_key='purge:'||j.id||':'||k AND m.status='DONE'))THEN RETURN jsonb_build_object('success',false,'result','MEDIA_INCOMPLETE');END IF;snap:=to_jsonb(l);UPDATE offer_threads SET original_listing_id=coalesce(original_listing_id,l.id),listing_snapshot=coalesce(listing_snapshot,snap),listing_id=NULL WHERE listing_id=l.id;UPDATE reports SET historical_listing_id=coalesce(historical_listing_id,l.id),listing_snapshot=coalesce(listing_snapshot,snap),listing_id=NULL WHERE listing_id=l.id;UPDATE payments SET historical_target_listing_id=coalesce(historical_target_listing_id,l.id),target_listing_snapshot=coalesce(target_listing_snapshot,snap),target_listing_id=NULL WHERE target_listing_id=l.id;DELETE FROM listing_images WHERE listing_id=l.id;DELETE FROM vehicle_details WHERE listing_id=l.id;DELETE FROM property_details WHERE listing_id=l.id;DELETE FROM favorites WHERE listing_id=l.id;DELETE FROM listing_price_history WHERE listing_id=l.id;DELETE FROM listings WHERE id=l.id;UPDATE listing_purge_jobs SET status='DONE',completed_at=now(),lease_until=NULL,worker_id=NULL,lock_token=NULL,last_error=NULL WHERE id=i;RETURN jsonb_build_object('success',true,'result','DONE','listing_id',l.id);END$$;
DO $$DECLARE r record;BEGIN FOR r IN SELECT p.oid::regprocedure s FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public'AND p.proname IN('canonical_sanboard_media_key','is_media_key_referenced','enqueue_media_cleanup_job','enqueue_listing_purge_job','discover_listing_purge_jobs','claim_listing_purge_jobs','retry_listing_purge_job','claim_media_cleanup_jobs','complete_media_cleanup_job','retry_media_cleanup_job','requeue_media_cleanup_job','replace_listing_images_atomic','complete_listing_purge_media_key','finalize_listing_purge')LOOP EXECUTE'REVOKE ALL ON FUNCTION '||r.s||' FROM PUBLIC,anon,authenticated';EXECUTE'GRANT EXECUTE ON FUNCTION '||r.s||' TO service_role';END LOOP;END$$;
COMMIT;
